const TEXT_DECODER = new TextDecoder();
const TEXT_ASSETS = {
  "/": { type: "text/html; charset=utf-8", body: "" },
  "/index.html": { type: "text/html; charset=utf-8", body: "" },
  "/style.css": { type: "text/css; charset=utf-8", body: "" },
  "/main.js": { type: "application/javascript; charset=utf-8", body: "" }
};

function decodeText(base64) {
  const bytes = Uint8Array.from(atob(base64), char => char.charCodeAt(0));
  return TEXT_DECODER.decode(bytes);
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const pathname = url.pathname === "" ? "/" : url.pathname;
    if (pathname === "/favicon.ico") return new Response(null, { status: 204 });
    const asset = TEXT_ASSETS[pathname];
    if (asset) {
      return new Response(decodeText(asset.body), {
        headers: { "content-type": asset.type, "cache-control": "no-store" }
      });
    }
    if (env.ASSETS) return env.ASSETS.fetch(request);
    return new Response("Not found", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
  }
};
